var m = tree.current_scene
var dd = m.get_node("ScrollContainer/MenuContainer/ArmySection/Player1Container/Player1Dropdown")
var idx = -1
for i in range(m.army_options.size()):
	if str(m.army_options[i].id) == "ork11e_codex_test":
		idx = i
if idx < 0:
	return "missing"
dd.select(idx)
dd.item_selected.emit(idx)
return str(m.army_options[dd.selected].id)

var m = tree.current_scene
var dd = m.get_node("ScrollContainer/MenuContainer/ArmySection/Player2Container/Player2Dropdown")
return str(m.army_options[dd.selected].id)

var f = tree.root.get_node_or_null("Main/FormationsDialog")
if f != null:
	f.hide()
return true

var mm = RulesEngine.get_unit_melee_weapons("U_TANKBUSTAS_A")
var out = [mm.get("m0", [])]
var gits = 0
for i in range(1, 6):
	if mm.get("m%d" % i, []) == ["Gitstikka"]:
		gits += 1
out.append("%d Gitstikka" % gits)
return out

var u = GameState.get_unit("U_WARBIKERS_A")
var w = RulesEngine.get_unit_weapons("U_WARBIKERS_A")
var nob = w.get(str(u.models[0].id), [])
var biker = w.get(str(u.models[1].id), [])
nob.sort()
return [nob, biker]

var out = []
for w in GameState.get_unit("U_WARBIKERS_A")["meta"]["weapons"]:
	if str(w.name).begins_with("Dual Kombi-rokkit"):
		out.append("%s %s A%s S%s" % [w.name, w.range, w.attacks, w.strength])
out.sort()
return out
